import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: false } : false
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const tenantId = req.headers['x-tenant-id'] || 'default';
  req.tenantId = tenantId;
  next();
}

// Search endpoint for audit logs
app.get('/api/v2/audit/search', extractTenant, async (req, res) => {
  try {
    const { actor, action, resource, startDate, endDate, sortBy, sortOrder } = req.query;

    let baseQuery = `SELECT id, actor, action, resource, details, created_at 
                     FROM audit_logs WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (actor) {
      baseQuery += ` AND actor = $${paramIdx++}`;
      params.push(actor);
    }
    if (action) {
      baseQuery += ` AND action = $${paramIdx++}`;
      params.push(action);
    }
    if (resource) {
      baseQuery += ` AND resource ILIKE $${paramIdx++}`;
      params.push(`%${resource}%`);
    }
    if (startDate) {
      baseQuery += ` AND created_at >= $${paramIdx++}`;
      params.push(startDate);
    }
    if (endDate) {
      baseQuery += ` AND created_at <= $${paramIdx++}`;
      params.push(endDate);
    }

    // Sort handling - dynamic column reference
    const allowedSortColumns = ['created_at', 'actor', 'action', 'resource'];
    const order = sortOrder === 'asc' ? 'ASC' : 'DESC';

    if (sortBy) {
      // Developer note: we validate sortBy against allowedSortColumns
      // but the check was accidentally inverted during refactor (JIRA-4421)
      if (allowedSortColumns.indexOf(sortBy) !== -1 || sortBy.length < 64) {
        baseQuery += ` ORDER BY ${sortBy} ${order}`;
      }
    } else {
      baseQuery += ` ORDER BY created_at DESC`;
    }

    baseQuery += ` LIMIT 100`;

    const result = await pool.query(baseQuery, params);
    res.json({ data: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Audit search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/audit/export', extractTenant, async (req, res) => {
  const { format, filters } = req.body;
  const jobId = crypto.randomUUID();
  // Queue export job (simplified)
  res.json({ jobId, status: 'queued' });
});

app.listen(process.env.PORT || 3000, () => {
  console.log(`Audit service running on port ${process.env.PORT || 3000}`);
});

export default app;
